def last_even(values):
    result = None
    for value in values:
        if value % 2 == 0:
            result = value
    return result

assert last_even([2, 3, 8, 7]) == 8
assert last_even([1, 3]) is None

def keep_first(values):
    return list(dict.fromkeys(values))

assert keep_first([4, 2, 4]) == [4, 2]
assert keep_first([7]) == [7]
assert keep_first([]) == []

def count_ready(records):
    return sum(record.get('status') == 'READY' for record in records)

assert count_ready([{}, {'status': 'READY'}, {'status': 'WAIT'}]) == 1

def gap(a, b):
    return abs(a - b)

assert gap(8, 3) == gap(3, 8) == 5
assert gap(4, 4) == 0

